from save import save
def R(*a): return [{"da":d,"en":e} for d,e in a]
N={}
N["en bestseller"]={"explanation":'"En bestseller" means "a bestseller". To say a book is among the best-selling ones, use "en bestsellerliste" (a bestseller list): "Bogen ligger på bestsellerlisten" (The book is on the bestseller list).',"related":R(("en forfatter","an author"),("en roman","a novel"),("et forlag","a publisher"),("en topliste","a chart"))}
N["en bestyrelse"]={"explanation":'"En bestyrelse" means "a board", as in the group that leads a company or an association. To say you are a member, use "at sidde i" (to sit in): "Hun sidder i bestyrelsen" (She is on the board).',"related":R(("et bestyrelsesmedlem","a board member"),("en formand","a chairman"),("en direktion","an executive board"),("en generalforsamling","a general meeting"))}
N["en besætning"]={"explanation":'"En besætning" means "a crew", as in the people working on a ship or a plane. On a farm, it also means all the animals kept there: "en kvægbesætning" (a herd of cattle).',"related":R(("et mandskab","a work crew"),("en kaptajn","a captain"),("en pilot","a pilot"))}
N["en besættelse"]={"explanation":'"En besættelse" means "an occupation", as in an army taking over a country (never a job). In Denmark, "besættelsen" (the occupation) is the name for the German occupation from 1940 to 1945. When you cannot stop thinking about something, it also means "obsession": "Det er blevet en besættelse for ham" (It has become an obsession for him).',"related":R(("at besætte","to occupy"),("en befrielse","a liberation"),("en tvangstanke","an obsessive thought"),("en passion","a passion"))}
N["en besøgende"]={"explanation":'"En besøgende" means "a visitor". It comes from "at besøge" (to visit). To say something is for the visitors, use "til" (for): "Der er gratis kaffe til de besøgende" (There is free coffee for the visitors).',"related":R(("en gæst","a guest"),("et besøg","a visit"),("en turist","a tourist"))}
N["en betaling"]={"explanation":'"En betaling" means "a payment". To say how you pay, use "med" (by): "betaling med kort" (payment by card).',"related":R(("at betale","to pay"),("en regning","a bill"),("et beløb","an amount"),("en kvittering","a receipt"))}
N["en betalingsmetode"]={"explanation":'"En betalingsmetode" means "a payment method". It is built from "en betaling" (a payment) and "en metode" (a method). In Denmark, "MobilePay" (a Danish phone payment app) is one payment method.',"related":R(("et kreditkort","a credit card"),("et dankort","a Dankort (debit card)"),("kontanter","cash"),("et betalingskort","a payment card"))}
N["en betingelse"]={"explanation":'"En betingelse" means "a condition", as in something that must be true first. For how a person or thing is doing, such as health, use "en tilstand" (a state): "Patientens tilstand er god" (The patient\'s condition is good).',"related":R(("et krav","a requirement"),("en forudsætning","a prerequisite"),("et vilkår","a term"),("en klausul","a clause"))}
N["en betjent"]={"explanation":'"En betjent" means "a police officer". A longer word for the same job is "en politibetjent" (a police officer). To say what an officer does on the road, say: "Betjenten standser bilen" (The officer stops the car).',"related":R(("politiet","the police"),("en brandmand","a firefighter"),("et politistation","a police station"))}
N["en betragtning"]={"explanation":'"En betragtning" means "a consideration". To share your thoughts on a matter, use the plural: "Jeg har nogle betragtninger om sagen" (I have some thoughts on the matter).',"related":R(("en overvejelse","a careful thought"),("at betragte","to look at, to consider"),("en holdning","an attitude"),("en synsvinkel","a viewpoint"))}
N["en betydning"]={"explanation":'"En betydning" means "a meaning". When something matters, it also means "importance": "Det har stor betydning" (It matters a lot).',"related":R(("at betyde","to mean"),("en mening","an opinion"),("en forklaring","an explanation"))}
N["en betændelse"]={"explanation":'"En betændelse" means "an inflammation". When you talk about an infection, it also means "infection": "en betændelse i øret" (an ear infection).',"related":R(("en byld","a boil"),("en blodforgiftning","blood poisoning"),("en feber","a fever"),("en hævelse","a swelling"))}
N["en beundrer"]={"explanation":'"En beundrer" means "an admirer". It comes from "at beundre" (to admire). To talk about someone who is secretly in love with you, add "hemmelig" (secret): "en hemmelig beundrer" (a secret admirer).',"related":R(("en fan","a fan"),("en tilhænger","a supporter"),("en tilbeder","a worshipper"))}
N["en bevilling"]={"explanation":'"En bevilling" means "a grant", as in money from an authority or a fund. When you talk about an official permit, it also means "permit": "en bevilling til at sælge alkohol" (a permit to sell alcohol).',"related":R(("at bevilge","to approve money for"),("et tilskud","a subsidy"),("en støtte","a support payment"),("en tilladelse","a permit"))}
N["en bevægelse"]={"explanation":'"En bevægelse" means "a movement". To say something is in motion, use "i" (in): "Toget er i bevægelse" (The train is in motion). When you talk about a group working for a cause, it also means "movement": "arbejderbevægelsen" (the labor movement).',"related":R(("at bevæge sig","to move"),("bevægelig","movable"),("ubevægelig","motionless"))}
N["en bh"]={"explanation":'"En bh" means "a bra". To say you put one on, use "at tage på" (to put on): "Hun tager sin bh på" (She puts on her bra).',"related":R(("en brystholder","a bra (the full word)"),("trusser","panties"),("undertøj","underwear"))}
N["en bi"]={"explanation":'"En bi" means "a bee". To say a bee stung you, use "at stikke" (to sting): "Jeg blev stukket af en bi" (I was stung by a bee).',"related":R(("honning","honey"),("en humlebi","a bumblebee"),("en bikube","a beehive"))}
N["en biavler"]={"explanation":'"En biavler" means "a beekeeper". It is built from "en bi" (a bee) and "at avle" (to breed). To say someone keeps bees, use "at holde bier" (to keep bees): "Min nabo holder bier" (My neighbor keeps bees).',"related":R(("en bikube","a beehive"),("et bistik","a bee sting"),("en bidronning","a queen bee"),("en bisværm","a swarm of bees"))}
N["en bibel"]={"explanation":'"En bibel" means "a bible". When you call a book the main guide in a field, it also means "bible": "Bogen er kokkenes bibel" (The book is the chefs\' bible).',"related":R(("et evangelium","a gospel"),("Koranen","the Koran"),("et testamente","a testament"),("bibelsk","biblical"))}
N["en bibliotekar"]={"explanation":'"En bibliotekar" means "a librarian". The ending "-ar" also makes a word for a person in "en arkivar" (an archivist): "Arkivaren finder gamle papirer" (The archivist finds old papers).',"related":R(("et bibliotek","a library"),("et udlån","a loan"),("en læsesal","a reading room"))}
N["en bidragyder"]={"explanation":'"En bidragyder" means "a contributor". It is built from "et bidrag" (a contribution) and "at yde" (to provide). To say someone gives a lot, add "stor" (big): "Firmaet er en stor bidragyder" (The company is a major contributor).',"related":R(("at bidrage","to contribute"),("en donor","a donor"),("en medvirkende","a participant"))}
N["en bikini"]={"explanation":'"En bikini" means "a bikini". For a one-piece swimsuit, use "en badedragt" (a swimsuit): "Hun har en badedragt på" (She is wearing a swimsuit).',"related":R(("badebukser","swim trunks"),("en badehætte","a swim cap"),("et badehåndklæde","a bath towel"))}
N["en bil"]={"explanation":'"En bil" means "a car". To say you go by car, use "i bil" (by car), without "en": "Vi kører i bil til Aarhus" (We are going to Aarhus by car).',"related":R(("en cykel","a bike"),("en bus","a bus"),("et tog","a train"),("en bilist","a motorist"))}
N["en bilist"]={"explanation":'"En bilist" means "a motorist". It is built from "en bil" (a car) and "-ist". The ending "-ist" makes a word for a person in "en pianist" (a pianist) and "en turist" (a tourist).',"related":R(("en cyklist","a cyclist"),("en motorcyklist","a motorcyclist"),("en fodgænger","a pedestrian"),("en chauffør","a driver"))}
